INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Projektstrukturplan immer unveränderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Kann während des Projekts angepasst werden"}, {"text": "Ja", "correct": false, "because": "Flexibel bei Änderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Projektstrukturplans?', 3, '[{"text": "Projektarbeit strukturieren", "correct": true, "because": "Zerlegt Projekt in Arbeitspakete"}, {"text": "Code schreiben", "correct": false, "because": "Nicht Programmierung"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Planungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente enthält ein Projektstrukturplan typischerweise?', 5, '[{"text": "Arbeitspakete", "correct": true, "because": "Zerlegen Aufgaben"}, {"text": "Hierarchische Struktur", "correct": true, "because": "Zeigt Abhängigkeiten"}, {"text": "Farbcodes", "correct": false, "because": "Nur gestalterisch"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Projektstrukturplan zeigt Arbeitspakete. b) Er ersetzt die Zeitplanung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ergänzt, nicht ersetzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung eines Projektstrukturplans?', 4, '[{"text": "Aufgabenzerlegung", "correct": false, "because": "Kern des Plans"}, {"text": "Abhängigkeiten", "correct": false, "because": "Strukturieren Arbeit"}, {"text": "Bildbearbeitung", "correct": true, "because": "Irrelevant für Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Projektstrukturplan nur für IT-Projekte genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Projektarten geeignet"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ist für einen Projektstrukturplan zentral?', 3, '[{"text": "Zerlegung in Arbeitspakete", "correct": true, "because": "Ermöglicht Übersicht"}, {"text": "Hohe Komplexität", "correct": false, "because": "Klarheit wichtiger"}, {"text": "Manuelle Erstellung", "correct": false, "because": "Tools effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Projektstrukturplan?', 5, '[{"text": "Klarheit", "correct": true, "because": "Zeigt Struktur"}, {"text": "Planungsgrundlage", "correct": true, "because": "Unterstützt Zeit- und Ressourcenplanung"}, {"text": "Maximale Details", "correct": false, "because": "Übersicht wichtiger"}, {"text": "Grafische Animationen", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Projektstrukturplan zeigt Hierarchien. b) Er enthält nur Zeitpläne. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Zeitplanung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Projektstrukturplan?', 4, '[{"text": "Arbeitspakete", "correct": false, "because": "Kern des Plans"}, {"text": "Hierarchie", "correct": false, "because": "Zeigt Struktur"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Projektstrukturplan dasselbe wie ein Gantt-Diagramm?', 2, '[{"text": "Nein", "correct": true, "because": "Gantt zeigt Zeit, PSP Struktur"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen enthält ein Projektstrukturplan?', 4, '[{"text": "Aufgaben", "correct": true, "because": "Zerlegt Projekt"}, {"text": "Abhängigkeiten", "correct": true, "because": "Zeigt Beziehungen"}, {"text": "Büroausstattung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Projektstrukturplan nur für Planer relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Team und Stakeholder nutzen"}, {"text": "Ja", "correct": false, "because": "Breite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Erstellung eines Projektstrukturplans?', 3, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Viele Ebenen", "correct": false, "because": "Übersicht wichtiger"}, {"text": "Manuelle Zeichnung", "correct": false, "because": "Tools effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Projektstrukturplan hilft bei der Ressourcenplanung. b) Er zeigt nur Zeitpläne.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Zeitplanung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen die Erstellung eines Projektstrukturplans?', 5, '[{"text": "MS Project", "correct": true, "because": "Visualisiert Strukturen"}, {"text": "Mindmapping-Software", "correct": true, "because": "Zeigt Hierarchien"}, {"text": "Musikwiedergabe", "correct": false, "because": "Kein Planungstool"}, {"text": "Texteditor", "correct": false, "because": "Ungeeignet für Visualisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Projektstrukturplan unwichtig?', 3, '[{"text": "Arbeitspakete", "correct": false, "because": "Kern des Plans"}, {"text": "Hierarchie", "correct": false, "because": "Zeigt Struktur"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Planungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Projektstrukturplan für agile Projekte geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Strukturiert auch agile Aufgaben"}, {"text": "Nein", "correct": false, "because": "Flexibel anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Projektstrukturplan Zeitpläne?', 3, '[{"text": "Nein", "correct": true, "because": "Fokussiert auf Struktur, nicht Zeit"}, {"text": "Ja", "correct": false, "because": "Zeit in Gantt-Diagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Projektstrukturplan?', 4, '[{"text": "Zerlegung eines IT-Projekts", "correct": true, "because": "Strukturiert Arbeitspakete"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Planung"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
